package practice;

import java.util.Optional;
import java.util.concurrent.ConcurrentMap;

/**
 * Seat holds for one flight. The map (seat to customer) belongs to the flight and is shared: every
 * booking request builds its own SeatHolds over it, so requests for one seat can run on several
 * threads at once.
 */
public class SeatHolds {

    private final ConcurrentMap<String, String> holders;

    public SeatHolds(ConcurrentMap<String, String> holders) {
        this.holders = holders;
    }

    /** Who holds the seat now, if anyone. */
    public Optional<String> holderOf(String seat) {
        return Optional.ofNullable(holders.get(seat));
    }

    /** Puts the seat on hold for the customer. True when this customer now holds it. */
    public boolean reserve(String seat, String customer) {
        return holders.putIfAbsent(seat, customer) == null;
    }

    /** Gives up the customer's hold on the seat. True when a hold of this customer was removed. */
    public boolean release(String seat, String customer) {
        return holders.remove(seat, customer);
    }
}

package practice;

import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            ConcurrentHashMap<String, String> flight = new ConcurrentHashMap<>();
            System.out.println("rosa reserves 12C: " + new SeatHolds(flight).reserve("12C", "rosa"));
            System.out.println("finn reserves 12C: " + new SeatHolds(flight).reserve("12C", "finn"));
            System.out.println("holder of 12C: " + new SeatHolds(flight).holderOf("12C").orElse("nobody"));
            System.out.println("finn releases 12C: " + new SeatHolds(flight).release("12C", "finn"));
            System.out.println("rosa releases 12C: " + new SeatHolds(flight).release("12C", "rosa"));
            System.out.println("finn reserves 12C again: " + new SeatHolds(flight).reserve("12C", "finn"));
            System.out.println("rosa's late second release: " + new SeatHolds(flight).release("12C", "rosa"));
            System.out.println("holder of 12C at the end: " + new SeatHolds(flight).holderOf("12C").orElse("nobody"));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

